<template>
  <el-menu
    :default-active="$route.name"
    class="el-menu-vertical-demo"
    @select="handleSelect"
  >
    <template v-for="route in filteredRoutes">
      <!-- 一级菜单（含子路由） -->
      <el-submenu
        v-if="hasNestedChildren(route)"
        :key="`sub_${route.path}`"
        :index="route.name"
      >
        <template #title>
          <i :class="`icon iconf-${route.meta.icon}`"></i>
          <span>{{ route.meta.title }}</span>
        </template>
        
        <!-- 遍历二级路由 -->
        <template v-for="child in route.children">
          <!-- 二级菜单（含三级子路由） -->
          <el-submenu
            v-if="hasNestedChildren(child)"
            :key="`sub_${child.path}`"
            :index="child.name"
          >
            <template #title>
              <i :class="`icon iconf-${child.meta.icon}`"></i>
              <span>{{ child.meta.title }}</span>
            </template>
            
            <!-- 三级菜单项 -->
            <el-menu-item
              v-for="grandChild in child.children"
              v-show="!grandChild.meta.hidden"
              :key="grandChild.path"
              :index="grandChild.name"
            >
              <i :class="`icon iconf-${grandChild.meta.icon}`"></i>
              <span>{{ grandChild.meta.title }}</span>
            </el-menu-item>
          </el-submenu>
          
          <!-- 二级普通菜单项 -->
          <el-menu-item
            v-else
            v-show="!child.meta.hidden"
            :key="`item_${child.path}`"
            :index="child.name"
          >
            <i :class="`icon iconf-${child.meta.icon}`"></i>
            <span>{{ child.meta.title }}</span>
          </el-menu-item>
        </template>
      </el-submenu>
      
      <!-- 一级普通菜单项 -->
      <el-menu-item
        v-else
        :key="`item_${route.path}`"
        :index="route.name"
      >
        <i :class="`icon iconf-${route.meta.icon}`"></i>
        <span>{{ route.meta.title }}</span>
      </el-menu-item>
    </template>
  </el-menu>
</template>

<script>
export default {
  computed: {
    routes() {
      return this.$router.options.routes[0].children || []
    },
    filteredRoutes() {
      return this.routes.filter(
        route => route.meta?.title && !route.meta?.hidden
      )
    }
  },
  methods: {
    // 检查是否有可见的嵌套子路由
    hasNestedChildren(route) {
      return route.children?.some(child => !child.meta?.hidden)
    },
    
    handleSelect(key) {
      this.$router.push({ name: key })
    }
  }
}
</script>

<style lang="less" scoped>
.icon {
  color: #2098e4;
  margin-right: 10px;
}

::v-deep(.el-menu-item),
::v-deep(.el-submenu__title) {
  .icon {
    vertical-align: middle;
    margin-right: 8px;
    width: 18px;
    text-align: center;
  }
}

::v-deep(.el-menu-item.is-active) {
  background: aliceblue;
}
</style>